CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,salt TEXT NOT NULL,hash TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL,expires TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS progress(user_id INTEGER NOT NULL,word_id INTEGER NOT NULL,level INTEGER NOT NULL DEFAULT 0,correct INTEGER NOT NULL DEFAULT 0,wrong INTEGER NOT NULL DEFAULT 0,updated TEXT NOT NULL,PRIMARY KEY(user_id,word_id));
CREATE TABLE IF NOT EXISTS exercise_progress(user_id INTEGER NOT NULL,exercise_id INTEGER NOT NULL,mode TEXT NOT NULL,correct INTEGER NOT NULL DEFAULT 0,wrong INTEGER NOT NULL DEFAULT 0,updated TEXT NOT NULL,PRIMARY KEY(user_id,exercise_id,mode));
CREATE TABLE IF NOT EXISTS library_words(id INTEGER PRIMARY KEY,word TEXT NOT NULL,meaning TEXT NOT NULL DEFAULT '',ipa TEXT NOT NULL DEFAULT '',example TEXT NOT NULL DEFAULT '',topic TEXT NOT NULL DEFAULT 'General',emoji TEXT NOT NULL DEFAULT '📚',stage TEXT NOT NULL DEFAULT 'A1',pos TEXT NOT NULL DEFAULT '',source TEXT NOT NULL DEFAULT 'curated',source_id TEXT NOT NULL DEFAULT '',license TEXT NOT NULL DEFAULT '',reviewed INTEGER NOT NULL DEFAULT 0,UNIQUE(word,source));
CREATE TABLE IF NOT EXISTS library_grammar(id INTEGER PRIMARY KEY,level TEXT NOT NULL,title TEXT NOT NULL,explanation TEXT NOT NULL DEFAULT '',example TEXT NOT NULL DEFAULT '',source TEXT NOT NULL DEFAULT 'curated',source_id TEXT NOT NULL DEFAULT '',license TEXT NOT NULL DEFAULT '',reviewed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS library_sentences(id INTEGER PRIMARY KEY,english TEXT NOT NULL,vietnamese TEXT NOT NULL DEFAULT '',level TEXT NOT NULL DEFAULT 'A1',source TEXT NOT NULL DEFAULT 'curated',source_id TEXT NOT NULL DEFAULT '',license TEXT NOT NULL DEFAULT '',reviewed INTEGER NOT NULL DEFAULT 0,UNIQUE(english,source));
CREATE TABLE IF NOT EXISTS library_exercises(id INTEGER PRIMARY KEY,mode TEXT NOT NULL,level TEXT NOT NULL,prompt TEXT NOT NULL,answer TEXT NOT NULL,explanation TEXT NOT NULL DEFAULT '',source TEXT NOT NULL DEFAULT 'curated',source_id TEXT NOT NULL DEFAULT '',reviewed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS library_results(user_id INTEGER NOT NULL,exercise_id INTEGER NOT NULL,correct INTEGER NOT NULL DEFAULT 0,wrong INTEGER NOT NULL DEFAULT 0,updated TEXT NOT NULL,PRIMARY KEY(user_id,exercise_id));
CREATE INDEX IF NOT EXISTS idx_library_words_stage ON library_words(stage,reviewed);
CREATE INDEX IF NOT EXISTS idx_library_exercises_level ON library_exercises(level,mode,reviewed);
